Tool response:
Tool: search_care_teams
Description: Search for a care team by patient identifier and target organization name.

Retrieves the internal ID of a care team associated with a specific patient 
and targeting a particular organization via an active consent.
Parameters:
    {
      "type": "object",
      "properties": {
        "patient_identifier": {
          "type": "string",
          "description": "The patient identifier (e.g., PT-789456)",
          "title": "Patient Identifier"
        },
        "target_organization_name": {
          "type": "string",
          "description": "The name of the target organization (e.g., MetroHealth Behavioral Health Network)",
          "title": "Target Organization Name"
        }
      },
      "required": [
        "patient_identifier",
        "target_organization_name"
      ]
    }

Tool response:
Tool: initiate_data_exchange
Description: Initiate a consent-gated FHIR-based data exchange.

Creates a new data exchange from a CareTeam to a target organization for a specific patient,
sharing the latest active Care Plan and a specified discharge summary document.
Parameters:
    {
      "type": "object",
      "properties": {
        "patient_identifier": {
          "type": "string",
          "description": "The patient identifier (e.g., PT-789456)",
          "title": "Patient Identifier"
        },
        "target_organization_name": {
          "type": "string",
          "description": "The name of the target organization (e.g., MetroHealth Behavioral Health Network)",
          "title": "Target Organization Name"
        },
        "discharge_summary_tag": {
          "type": "string",
          "description": "Tag identifying the discharge summary document (e.g., DISCHARGE_20240512)",
          "title": "Discharge Summary Tag"
        },
        "care_team_id": {
          "type": "integer",
          "description": "The ID of the source care team initiating the exchange",
          "title": "Care Team Id"
        },
        "consent_id": {
          "type": "integer",
          "description": "The ID of the consent granting permission for this exchange",
          "title": "Consent Id"
        },
        "initiated_by_user_id": {
          "type": "integer",
          "description": "The ID of the user initiating the exchange",
          "title": "Initiated By User Id"
        }
      },
      "required": [
        "patient_identifier",
        "target_organization_name",
        "discharge_summary_tag",
        "care_team_id",
        "consent_id",
        "initiated_by_user_id"
      ]
    }
